#!/usr/bin/env node
'use strict';

// Generates the TypeScript wire-type layer for the `cluster` client subpath from the
// authoritative protocol/openengine-cluster/v1 JSON Schema/OpenRPC artifacts. Rust/OpenRPC
// remain the only wire authority; this script is the sole path from schema to TS types, so
// hand-maintained duplicate DTOs never drift from what the server actually speaks.
//
// Usage:
//   node scripts/generate-cluster-protocol-ts.js            # write generated files
//   node scripts/generate-cluster-protocol-ts.js --check     # exit 1 on drift, write nothing

const fs = require('fs');
const path = require('path');
const { compile } = require('json-schema-to-typescript');
const prettier = require('prettier');
const prettierConfig = require('../.prettierrc.json');

const REPO_ROOT = path.resolve(__dirname, '..');
const PROTOCOL_DIR = path.join(REPO_ROOT, 'protocol', 'openengine-cluster', 'v1');
const SCHEMA_PATH = path.join(PROTOCOL_DIR, 'schema.json');
const OPENRPC_PATH = path.join(PROTOCOL_DIR, 'openrpc.json');
const OUT_DIR = path.join(REPO_ROOT, 'src', 'cluster', 'generated');
const WIRE_TYPES_PATH = path.join(OUT_DIR, 'wire-types.ts');
const METHODS_PATH = path.join(OUT_DIR, 'methods.ts');

const SYNTHETIC_ROOT_NAME = 'ClusterProtocolGeneratedRootMarker';

// Every JSON-RPC method result/params type, plus the generic subscription-framing envelope
// bodies (`event`, `subscription/closed`, `subscription/cancel`, `$/cancelRequest`) documented
// on openrpc.json's `x-generic-subscription-framing`. This is the full v1 wire surface actually
// spoken by ClusterClient/subscription clients. Deliberately excludes schema.json's
// `JsonRpcRequest`/`JsonRpcSuccess`/`JsonRpcResponse`/`JsonRpcNotification` (and their numbered
// siblings) -- those are schemars' per-generic-instantiation artifacts of one Rust generic type;
// this client hand-declares that same generic shape once in src/cluster/transport.ts instead of
// importing a dozen monomorphized copies. Also excludes WorkerDescriptor/LegacyShipRequest/
// LegacyShipResult/CompiledGraphIr: legacy-worker-binding and internal-IR schemas that no v1
// JSON-RPC method takes or returns.
const ROOT_DEFS = [
  'RequestId',
  'JsonRpcError',
  'JsonRpcErrorResponse',
  'DomainErrorData',
  'CancelRequestParams',
  'SubscriptionCancelParams',
  'SubscriptionCloseReason',
  'SubscriptionClosedNotification',
  'EventNotification',
  'WatchEvent',
  'InitializeParams',
  'InitializeResult',
  'PlanParams',
  'PlanResult',
  'ApplyParams',
  'ApplyResult',
  'GetParams',
  'GetResult',
  'UpdateParams',
  'UpdateResult',
  'StopParams',
  'StopResult',
  'RetryParams',
  'RetryResult',
  'ResubmitParams',
  'ResubmitResult',
  'DeleteParams',
  'DeleteResult',
  'WatchParams',
  'WatchResult',
  'LogsParams',
  'LogsResult',
  'LogEventNotification',
  'LogsClosedNotification',
  'AgentAttachParams',
  'AgentAttachResult',
  'AgentAttachEventNotification',
  'AgentAttachClosedNotification',
  'AgentAttachEvent',
];

const GENERATED_FILE_NOTICE = `/**
 * AUTO-GENERATED FILE -- DO NOT EDIT BY HAND.
 *
 * Generated by scripts/generate-cluster-protocol-ts.js from the authoritative
 * protocol/openengine-cluster/v1/schema.json JSON Schema. Run
 * \`npm run generate:cluster-protocol-ts\` to regenerate after the schema changes, and
 * \`npm run generate:cluster-protocol-ts -- --check\` to verify there is no drift.
 */
`;

// json-schema-to-typescript's own output can trip stylistic rules this package enforces on
// hand-written code (e.g. consistent-type-imports has nothing to say here, but a future schema
// shape could emit something else it dislikes); wire-types.ts gets a blanket disable so
// generator changes never need a matching eslint-config change. methods.ts is a small hand-
// templated file that already satisfies the linter on its own, so it does not need one --- an
// unused `eslint-disable` is itself a lint error in this repo's config.
const WIRE_TYPES_BANNER = `/* eslint-disable */\n${GENERATED_FILE_NOTICE}`;
const METHODS_BANNER = GENERATED_FILE_NOTICE;

function pascalCaseMethodSegment(name) {
  return name
    .split('/')
    .map((segment) => segment.charAt(0).toUpperCase() + segment.slice(1))
    .join('');
}

async function generateWireTypes(schema) {
  const root = {
    $schema: schema.$schema,
    $defs: schema.$defs,
    type: 'object',
    properties: Object.fromEntries(ROOT_DEFS.map((name) => [name, { $ref: `#/$defs/${name}` }])),
    required: ROOT_DEFS,
    additionalProperties: false,
  };

  for (const name of ROOT_DEFS) {
    if (!schema.$defs || !schema.$defs[name]) {
      throw new Error(`generate-cluster-protocol-ts: schema.json is missing $defs/${name}`);
    }
  }

  const compiled = await compile(root, SYNTHETIC_ROOT_NAME, {
    cwd: PROTOCOL_DIR,
    unreachableDefinitions: false,
    bannerComment: '',
    additionalProperties: false,
    style: prettierConfig,
  });

  // The synthetic root interface exists only to force every listed $defs entry to be reachable
  // from compile()'s traversal; it carries no meaning of its own. json-schema-to-typescript does
  // not emit declarations in a stable position (the marker can land anywhere among its
  // dependencies), so it -- and its "referenced by" doc comment, if any -- is stripped by pattern
  // rather than by truncating the file at a discovered offset.
  const markerBlock = new RegExp(
    `(?:/\\*\\*[^]*?\\*/\\s*\\n)?export interface ${SYNTHETIC_ROOT_NAME} \\{[^]*?\\n\\}\\n`
  );
  if (!markerBlock.test(compiled)) {
    throw new Error(
      'generate-cluster-protocol-ts: could not locate synthetic root marker to strip'
    );
  }
  const body = compiled.replace(markerBlock, '');

  return WIRE_TYPES_BANNER + '\n' + body.trimStart().trimEnd() + '\n';
}

function generateMethods(openrpc) {
  const methods = openrpc.methods.map((method) => {
    const pascal = pascalCaseMethodSegment(method.name);
    return { name: method.name, paramsType: `${pascal}Params`, resultType: `${pascal}Result` };
  });

  const importedTypes = Array.from(
    new Set(methods.flatMap((method) => [method.paramsType, method.resultType]))
  ).sort();

  const mapEntries = methods
    .map(
      (method) =>
        `  ${JSON.stringify(method.name)}: { params: ${method.paramsType}; result: ${method.resultType} };`
    )
    .join('\n');

  const namesArray = methods.map((method) => JSON.stringify(method.name)).join(', ');

  return `${METHODS_BANNER}
import type { ${importedTypes.join(', ')} } from './wire-types.js';

/** Maps every v1 JSON-RPC method name to its params/result wire types. */
export interface ClusterMethodMap {
${mapEntries}
}

export type ClusterMethodName = keyof ClusterMethodMap;

export const CLUSTER_METHOD_NAMES: readonly ClusterMethodName[] = [${namesArray}];
`;
}

async function generate() {
  const schema = JSON.parse(fs.readFileSync(SCHEMA_PATH, 'utf8'));
  const openrpc = JSON.parse(fs.readFileSync(OPENRPC_PATH, 'utf8'));
  const wireTypes = await generateWireTypes(schema);
  const methods = await prettier.format(generateMethods(openrpc), {
    ...prettierConfig,
    parser: 'typescript',
  });
  return { wireTypes, methods };
}

async function main() {
  const check = process.argv.includes('--check');
  const { wireTypes, methods } = await generate();

  if (check) {
    const drifted = [];
    for (const [outPath, content] of [
      [WIRE_TYPES_PATH, wireTypes],
      [METHODS_PATH, methods],
    ]) {
      const existing = fs.existsSync(outPath) ? fs.readFileSync(outPath, 'utf8') : null;
      if (existing !== content) {
        drifted.push(outPath);
      }
    }
    if (drifted.length > 0) {
      console.error('Cluster protocol TypeScript artifacts are out of date:');
      for (const outPath of drifted) {
        console.error(`  ${path.relative(REPO_ROOT, outPath)}`);
      }
      console.error('Run `npm run generate:cluster-protocol-ts` to regenerate.');
      process.exit(1);
    }
    console.log('Cluster protocol TypeScript artifacts are up to date.');
    return;
  }

  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(WIRE_TYPES_PATH, wireTypes);
  fs.writeFileSync(METHODS_PATH, methods);
  console.log(`Wrote ${path.relative(REPO_ROOT, WIRE_TYPES_PATH)}`);
  console.log(`Wrote ${path.relative(REPO_ROOT, METHODS_PATH)}`);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
